RAKIA.TEXTS.aspect["sun-moon"] = RAKIA.TEXTS.aspect["sun-moon"] || {};
RAKIA.TEXTS.aspect["sun-moon"].conjunction = T("צמידות בין שמש לירח ממזגת את הרצון ואת הרגש לקול אחד. הכוח כאן הוא אחדות פנימית, כשהראש והלב מסכימים. הקושי הוא שקשה לראות את התמונה מבחוץ, כי אין קול שני שמערער. למשל, בשיחה בארוחת ערב מי שנושא את זה בטוח שכולם רואים את הדברים כמוהו, ומופתע כשמישהו ליד השולחן חושב אחרת. מה שעוזר הוא לשאול איך זה נראה לאחרים, ולהקשיב לתשובה עד הסוף. האחדות הזאת היא מתנה, וגם היא אוהבת חלון פתוח.");
RAKIA.TEXTS.aspect["sun-moon"].sextile = T("שישית בין שמש לירח פותחת דלת בין מה שרוצים למה שמרגישים. יש כאן הזדמנות לחיות בשלום עם הצרכים, בלי מלחמה פנימית. ההזדמנות הזאת אינה נפתחת לבד: היא מבקשת יוזמה, למשל להקשיב לרגש לפני שמחליטים. בטיול משפחתי, למשל, קל למי שנושא את זה להרגיש שהוא עייף ולומר את זה בפשטות, במקום להמשיך ללכת ולכעוס. הקושי הוא שהדלת הפתוחה נראית מובנת מאליה, ואז שוכחים לעבור בה, ומה שעוזר הוא רגע קצר של בדיקה פנימית לפני כל בחירה. השקט הזה בין הראש ללב שווה טיפוח.");
RAKIA.TEXTS.aspect["sun-moon"].square = T("ריבוע בין שמש לירח יוצר חיכוך בין הרצון לצורך. מה שהלב מבקש לא מתאים למה שהאני מכריז, ושניהם מושכים לכיוונים שונים. למשל, מי שנושא את זה מתכנן ערב עם חברים כי כך הוא רואה את עצמו, וברגע האחרון מרגיש שהוא רוצה רק שקט בבית. החיכוך הזה מניע: הוא מכריח לברר מה באמת חשוב. מה שעוזר הוא לתת לשני הצדדים מקום, בלי לבחור אחד מהם לנצח, למשל ערב אחד בחוץ וערב אחד בבית. עם הזמן הריב הפנימי הופך לשיחה, והשיחה הזאת מלמדת הרבה.");
RAKIA.TEXTS.aspect["sun-moon"].trine = T("משולש בין שמש לירח מזרים את הרגש והרצון באותו כיוון. יש כאן נוחות פנימית ותחושה של בית מבפנים, גם כשבחוץ סוער. למשל, בעבודה בצוות מי שנושא את זה מרגיע את האווירה בלי מאמץ, רק בגלל שהוא שלם עם עצמו. הזרימה הקלה עלולה להירדם, ואז חסר הדחף לזוז, והימים דומים זה לזה. מה שמעיר אותה הוא אתגר שנבחר בכוונה: קורס חדש, מסלול הליכה לא מוכר, שיחה שדחו. הנוחות הזאת היא בסיס טוב, וכדאי לבנות עליו משהו.");
RAKIA.TEXTS.aspect["sun-moon"].opposition = T("ניגוד בין שמש לירח מותח חבל בין מה שמבקשים לבין מה שצריכים. הקוטב האחד רוצה להתבלט, והשני רוצה ביטחון ושקט. למשל, מי שנושא את זה מקבל הצעה להוביל פרויקט, שמח, ובאותו לילה שוכב ער ומתגעגע לשגרה הבטוחה. המתח הזה מבקש איזון, ולא ניצחון של צד אחד. מה שעוזר הוא לזכור ששני הקולות שייכים לאותו אדם, ולתת לכל אחד מהם יום משלו. כשמקשיבים לשניהם, המתיחה הופכת לרוחב.");

RAKIA.TEXTS.aspect["sun-mercury"] = RAKIA.TEXTS.aspect["sun-mercury"] || {};
RAKIA.TEXTS.aspect["sun-mercury"].conjunction = T("צמידות בין שמש למרקורי מחברת את הזהות למחשבה: מי שנושא את זה מזדהה עם הרעיונות שלו. הכוח הוא בהירות של דעה, ויכולת לומר בדיוק מה חושבים. הקושי הוא שקשה לשמוע ביקורת על רעיון בלי לחוש שהיא על האדם. למשל, בישיבת צוות מישהו מציע תיקון קטן להצעה, והתחושה היא שתקפו אישית. מה שעוזר הוא להפריד בין השניים, ולומר בשקט: זה רעיון, לא אדם. ההפרדה הזאת משחררת, וגם הופכת את הרעיונות לטובים יותר.");
RAKIA.TEXTS.aspect["sun-mercury"].sextile = T("שישית בין שמש למרקורי מזמינה לבטא את הרצון במילים ברורות. ההזדמנות כאן היא לדבר, לכתוב וללמוד מתוך תחושה של ערך. למשל, מי שנושא את זה יכול להסביר בארוחת ערב למה בחר בדרך מסוימת, ופתאום כולם מבינים אותו טוב יותר. היא מבקשת יוזמה: רעיון שלא נאמר בקול נשאר רעיון. הקושי הוא שהקלות הזאת נראית קטנה, ולכן דוחים את הדיבור לפעם אחרת. מה שעוזר הוא להתחיל מאמירה אחת קצרה, וחם לגלות כמה היא פותחת.");
RAKIA.TEXTS.aspect["sun-mercury"].square = T("ריבוע בין שמש למרקורי מביא חיכוך בין מה שרוצים לומר לבין מה שיוצא. המילים לא מדביקות את הכוונה, וזה מעצבן. למשל, מי שנושא את זה שולח הודעה מהירה, קורא אותה שוב ומגלה שהיא נשמעת קרה, למרות שהכוונה הייתה חמה. החיכוך הזה מניע לדייק, לבדוק ולנסח שוב. מה שעוזר הוא לתת למילים זמן לפני שאומרים אותן, ולשאול אם הן אומרות את מה שרוצים. עם התרגול, הפער בין הכוונה למילה נעשה קטן, ויש בזה סיפוק.");
RAKIA.TEXTS.aspect["sun-mercury"].trine = T("משולש בין שמש למרקורי נותן זרימה טבעית בין הכוונה למילה. יש כאן קלות בהסבר ובלמידה, ואנשים אוהבים להקשיב. למשל, בטיול מי שנושא את זה מסביר לחברים על המקום, והם זוכרים את הסיפור גם אחרי שנים. הקלות הזאת עלולה להירדם, ואז אומרים דברים בלי לחשוב לעומק. מה שמעיר אותה הוא שאלה קשה שנשאלת בכוונה, כזאת שאין לה תשובה מיידית. הכישרון לדבר הוא מתנה, ומתנה אוהבת שימוש מדויק.");
RAKIA.TEXTS.aspect["sun-mercury"].opposition = T("ניגוד בין שמש למרקורי מותח בין האני לבין המחשבה עליו. מצד אחד יש רצון ברור, ומצד שני קול שמפקפק ומנתח. למשל, מי שנושא את זה מחליט להירשם לקורס, ובדרך הביתה כבר שומע בראש עשר סיבות למה זה לא מתאים. המתח מבקש איזון: לא לתת לספק להשתיק את הרצון, ולא לתת לרצון להשתיק את הספק. מה שעוזר הוא לרשום את הרצון ואת הספק זה ליד זה, ולראות ששניהם עוזרים. הדו־שיח הפנימי הזה, כשמנהלים אותו ברוגע, מוביל להחלטות טובות.");

RAKIA.TEXTS.aspect["sun-venus"] = RAKIA.TEXTS.aspect["sun-venus"] || {};
RAKIA.TEXTS.aspect["sun-venus"].conjunction = T("צמידות בין שמש לונוס ממזגת את הזהות עם הצורך ביופי ובקשר. הכוח כאן הוא חן וחום שמושכים אנשים, וטעם טוב בכל דבר. הקושי הוא נטייה לרצות אחרים כדי להיות אהובים. למשל, בבחירת מסעדה עם חברים מי שנושא את זה אומר שהכול בסדר, ובסוף יושב במקום שלא אהב. מה שעוזר הוא לזכור שערך אינו תלוי בחיוך של אחרים, ולומר לפעמים מה רוצים באמת. החן נשאר גם כשאומרים לא, ולפעמים הוא אפילו גדל.");
RAKIA.TEXTS.aspect["sun-venus"].sextile = T("שישית בין שמש לונוס מציעה הזדמנות להביא נעימות ויופי לתוך מה שעושים. הרצון וההנאה יכולים ללכת יחד, בלי שאחד מהם מוותר. למשל, מי שנושא את זה מסדר את שולחן העבודה עם פרח ומוזיקה שקטה, ופתאום העבודה זורמת. ההזדמנות מבקשת יוזמה: להזמין, ליצור, לפנות אל מישהו ראשון. הקושי הוא שהנעימות נשארת בגדר רצון, ומחכים שאחרים יתחילו. מה שעוזר הוא צעד קטן ראשון, והחום שמגיע אחריו מספר את השאר.");
RAKIA.TEXTS.aspect["sun-venus"].square = T("ריבוע בין שמש לונוס מביא חיכוך בין מה שרוצים להיות לבין מה שרוצים שיאהבו. יש כאן פיתוי לוותר על עצמיות בשביל חיבה. למשל, מי שנושא את זה מסכים לתוכנית סוף שבוע שלא מתאימה לו, רק כדי לא לאכזב, ואחר כך מרגיש זר במקום שלו. החיכוך מניע לברר מה באמת נעים ומה רק נראה כך. מה שעוזר הוא לבחור ולא רק להתאים, ולומר בקול רך מה מתאים. מי שמעז לבחור מגלה שאוהבים אותו גם כך, ואולי דווקא כך.");
RAKIA.TEXTS.aspect["sun-venus"].trine = T("משולש בין שמש לונוס מזרים חן טבעי ורוך אל תוך האישיות. קל למי שנושא את זה למצוא חן ולהרגיש בנוח בחברה. למשל, במסיבה שבה איש אינו מכיר איש, הוא מוצא תוך דקות שיחה נעימה. הזרימה הזאת עלולה להירדם בנוחות, בלי מאמץ ובלי צמיחה. מה שמעיר אותה הוא לבחור משימה שאינה נעימה, למשל שיחה קשה שדוחים כבר שבועיים. הרוך הזה יפה במיוחד כשמצרפים אליו קצת אומץ.");
RAKIA.TEXTS.aspect["sun-venus"].opposition = T("ניגוד בין שמש לונוס מותח בין הצורך להיות עצמאי לבין הצורך להיות בקשר. קוטב אחד מבקש להוביל, והשני מבקש להסכים. למשל, בתכנון חופשה זוגית מי שנושא את זה רוצה לבחור בעצמו, ובאותו רגע רוצה שכולם יהיו מרוצים, ונתקע בין השניים. המתח הזה מבקש איזון, ולא ויתור. מה שעוזר הוא לומר בקול מה רוצים, בלי לוותר על העדינות, ולתת לאחר לומר גם. הריקוד בין עצמאות לקרבה נעשה קל יותר ככל שמתרגלים אותו.");

RAKIA.TEXTS.aspect["sun-mars"] = RAKIA.TEXTS.aspect["sun-mars"] || {};
RAKIA.TEXTS.aspect["sun-mars"].conjunction = T("צמידות בין שמש למאדים ממזגת את הרצון עם כוח הפעולה. יש כאן אומץ, יוזמה ואנרגיה שלא מחכה לאיש. הקושי הוא קוצר רוח וכעס שפורץ מהר. למשל, בנהיגה בפקק מי שנושא את זה מרגיש איך הדם עולה לראש, וכל נהג איטי נראה כמו אויב. מה שעוזר הוא להפנות את הכוח למטרה ברורה, ולא לוויכוח, למשל לריצה קצרה או למשימה עם התחלה וסוף. הדלק הזה יקר, וכשמכוונים אותו הוא מזיז הרים.");
RAKIA.TEXTS.aspect["sun-mars"].sextile = T("שישית בין שמש למאדים פותחת דלת לפעולה מתוך ביטחון. יש הזדמנות להתחיל דברים ולעמוד מאחוריהם, בלי להתנצל. למשל, מי שנושא את זה מציע בישיבה רעיון שאחרים חשבו עליו ולא העזו לומר, ומקבל את המשימה להוביל אותו. היא מבקשת יוזמה: הכוח הזה נשאר בכוח אם לא עושים צעד ראשון. הקושי הוא שהצעד נדחה, כי הכול נראה אפשרי גם מחר. מה שעוזר הוא להתחיל היום בדבר קטן, וההתחלה עצמה כבר מחממת.");
RAKIA.TEXTS.aspect["sun-mars"].square = T("ריבוע בין שמש למאדים יוצר חיכוך בין מה שרוצים לבין הדרך שבה נלחמים על זה. יש כאן הרבה דלק, ולעיתים הוא נשפך על ריב במקום על מטרה. למשל, מי שנושא את זה מתחיל ויכוח על מקום חניה, ומגלה אחרי חצי שעה שהוא שכח לאן בכלל נסע. החיכוך מניע להישגים, כשלומדים לכוון אותו. מה שעוזר הוא תנועה או משימה עם סוף ברור, כמו ניקיון של חדר אחד עד הסוף. הכעס הזה הוא כוח, ומי שמכוון אותו מגיע רחוק.");
RAKIA.TEXTS.aspect["sun-mars"].trine = T("משולש בין שמש למאדים מזרים אנרגיה חמה וישירה. מי שנושא את זה פועל בטבעיות ומאמין ביכולת שלו. למשל, כשהמכונית נתקעת בדרך לטיול, הוא כבר בחוץ, מארגן עזרה, בזמן שאחרים עוד מחפשים את הטלפון. הזרימה הזאת עלולה להירדם, ואז הכוח מתבזבז על מה שקל. מה שמעיר אותה הוא לבחור אתגר גדול מהרגיל, כזה שמפחיד קצת. הביטחון הטבעי הזה הוא מתנה, ומגיע לו יעד ראוי.");
RAKIA.TEXTS.aspect["sun-mars"].opposition = T("ניגוד בין שמש למאדים מותח חבל בין הזהות לבין הדחף להילחם. לפעמים הכעס מופנה החוצה, אל אנשים שמאתגרים, ולפעמים פנימה. למשל, מי שנושא את זה יוצא מפגישה עם הבוס רותח, ובבית מוצא את עצמו מתווכח עם הילדים על כלום. המתח מבקש איזון: להשתמש בכוח בלי להפוך כל מפגש למאבק. מה שעוזר הוא לשאול על מה באמת הריב, ולעצור רגע לפני התשובה. כשהכוח מוצא את המטרה הנכונה, הוא הופך מריב לעשייה.");

RAKIA.TEXTS.aspect["sun-jupiter"] = RAKIA.TEXTS.aspect["sun-jupiter"] || {};
RAKIA.TEXTS.aspect["sun-jupiter"].conjunction = T("צמידות בין שמש ליופיטר ממזגת את האני עם רוחב לב ואמונה. יש כאן אופטימיות, נדיבות ורצון לצמוח. הקושי הוא הגזמה: הבטחות גדולות מדי, ביטחון גדול מהמעשה. למשל, מי שנושא את זה מבטיח בארוחת ערב לארגן טיול גדול לכל המשפחה, וכעבור שבוע מגלה שלא בדק אפילו תאריך. מה שעוזר הוא לבדוק את המידה לפני שמתרחבים, ולהבטיח קצת פחות ממה שאפשר. הלב הרחב הזה מחמם את כולם, ומידה נכונה שומרת עליו.");
RAKIA.TEXTS.aspect["sun-jupiter"].sextile = T("שישית בין שמש ליופיטר מציעה הזדמנות לגדול: ללמוד, לנסוע במחשבה, לראות רחוק. הביטחון והרצון נפגשים, ומתוכם יוצאת שמחה. למשל, מי שנושא את זה פותח בשיחה נושא חדש, ולפתע כל השולחן סקרן ומדבר. ההזדמנות מבקשת יוזמה, כי דלת פתוחה אינה מזיזה את הרגליים. הקושי הוא שהתחושה הטובה מספיקה, ואז מדברים על הלימוד במקום ללמוד. מה שעוזר הוא להירשם, לפתוח את הספר, לצאת לדרך, והדרך עצמה משמחת.");
