RAKIA.TEXTS.aspect["sun-jupiter"].trine = T("משולש בין שמש ליופיטר מזרים ביטחון ושמחת חיים. קל למי שנושא את זה להאמין בטוב ולמשוך הזדמנויות. למשל, בעבודת צוות הוא זה שאומר שיהיה בסדר, וכולם נרגעים ומתחילים לעבוד. הזרימה הזאת עלולה להירדם בנוחות, ואז לא עושים את המאמץ, כי הכול מסתדר גם כך. מה שמעיר אותה הוא להתחייב למשהו שדורש עבודה, כמו לימוד שנמשך חודשים. האמונה הטובה הזאת מדבקת, וכשמצרפים אליה מעשה היא נעשית אמיתית.");
RAKIA.TEXTS.aspect["sun-jupiter"].opposition = T("ניגוד בין שמש ליופיטר מותח בין האני לבין הרצון לחרוג ממנו. קוטב אחד מבקש להיות מרכז, והשני מבקש להתרחב בלי גבול. למשל, מי שנושא את זה מספר סיפור בחברה, ותוך כדי הסיפור גדל, מתרחב, ובסוף גם הוא לא בטוח מה מתוכו באמת קרה. המתח מבקש איזון בין ביטחון לצניעות. מה שעוזר הוא לשאול אם ההבטחה גדולה מהמעשה, ולהקטין אותה קצת מראש. גם סיפור מדויק יכול להיות גדול, ויש בזה חן משלו.");

